import React, { useContext, useEffect, useState } from 'react';
import { Alert, Spinner } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { FaArrowLeft, FaBookOpen, FaCalendarDay, FaChalkboardTeacher, FaClock, FaSyncAlt } from 'react-icons/fa';
import { AuthContext } from '../../App';
import Layout from '../common/Layout';
import { fetchStaffDailyTimetable, fetchStaffPeriodTopicDetails } from '../../services/TimetableServices/timetableServices';

const getParams = (user) => ({
  stfid: user.stfid,
  instid: user.instid,
  brcid: user.brcid,
  acdmcyr: user.acdmcyr,
});

const displayDate = (value) => {
  if (!value) return 'Not scheduled';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
};

function TimetablePage() {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const navigate = useNavigate();
  const [periods, setPeriods] = useState([]);
  const [selectedPeriod, setSelectedPeriod] = useState(null);
  const [topicDetails, setTopicDetails] = useState([]);
  const [loading, setLoading] = useState(true);
  const [detailLoading, setDetailLoading] = useState(false);
  const [error, setError] = useState('');

  const loadTimetable = async () => {
    if (!user.stfid || !user.instid || !user.brcid || !user.acdmcyr) {
      setError('Staff timetable information is incomplete.');
      setLoading(false);
      return;
    }
    setLoading(true);
    setError('');
    const response = await fetchStaffDailyTimetable(getParams(user));
    setLoading(false);
    if (response?.status === 'success') setPeriods(response.payload || []);
    else setError(response?.error?.message || 'Unable to load today’s timetable.');
  };

  useEffect(() => { loadTimetable(); }, [user.stfid, user.instid, user.brcid, user.acdmcyr]);

  const openPeriod = async (period) => {
    setSelectedPeriod(period);
    setTopicDetails([]);
    setDetailLoading(true);
    const response = await fetchStaffPeriodTopicDetails({ ...getParams(user), clsprid: period.clsprid });
    setDetailLoading(false);
    if (response?.status === 'success') setTopicDetails(response.payload || []);
  };

  return (
    <Layout>
      <div className="tt-page">
        <header className="tt-header">
          <button type="button" className="hw-icon-btn" onClick={() => navigate('/dashboard')} aria-label="Go back"><FaArrowLeft /></button>
          <div><span className="hw-kicker">Daily schedule</span><h1>Today’s Timetable</h1><p>Your classes, subjects, and planned topics for today.</p></div>
          <button type="button" className="hw-icon-btn tt-refresh" onClick={loadTimetable} disabled={loading} aria-label="Refresh timetable"><FaSyncAlt /></button>
        </header>

        {error && <Alert variant="danger">{error}</Alert>}
        {loading ? <div className="tt-empty"><Spinner animation="border" /><p>Loading today’s classes...</p></div> : periods.length === 0 ? <div className="tt-empty"><FaCalendarDay /><h2>No classes today</h2><p>Your timetable is clear for today.</p></div> : (
          <div className="tt-period-list">
            {periods.map((period, index) => (
              <button type="button" className={`tt-period-card ${selectedPeriod?.clsprid === period.clsprid ? 'active' : ''}`} key={period.clsprid || index} onClick={() => openPeriod(period)}>
                <span className="tt-period-number">{index + 1}</span>
                <span className="tt-period-main"><strong>{period.subnm || period.subcd || 'Subject'}</strong><small><FaChalkboardTeacher /> {period.clsnm || 'Class'}{period.secnm ? ` · ${period.secnm}` : ''}</small></span>
                <span className="tt-period-time"><FaClock /> {period.prd || `Period ${index + 1}`}</span>
              </button>
            ))}
          </div>
        )}

        {selectedPeriod && <section className="tt-topic-panel">
          <div className="tt-topic-head"><div><span className="hw-kicker">Lesson details</span><h2>{selectedPeriod.subnm || 'Period topic'}</h2></div><span className="hw-status-badge">{selectedPeriod.prd}</span></div>
          {detailLoading ? <div className="tt-topic-loading"><Spinner animation="border" size="sm" /> Loading topic...</div> : topicDetails.length ? topicDetails.map((detail, index) => <article className="tt-topic-card" key={`${detail.clsprid}-${index}`}><span className={`tt-topic-tag ${detail.tag === 'RED' ? 'urgent' : ''}`}>{detail.tag === 'RED' ? 'Due soon' : 'On track'}</span><h3><FaBookOpen /> {detail.topic || 'Topic not added'}</h3><p>{detail.clsnm}{detail.secnm ? ` · ${detail.secnm}` : ''} · {detail.subnm}</p><small>{displayDate(detail.frmdt)} — {displayDate(detail.todt)}{detail.status ? ` · ${detail.status}` : ''}</small></article>) : <div className="tt-no-topic">No current topic details added for this period.</div>}
        </section>}
      </div>
    </Layout>
  );
}

export default TimetablePage;
